'use strict';
const $=id=>document.getElementById(id), E=EMEngine;
let db, notes=[], events=[], current, recording=false, starting=false, stream, recorder, recParts=[], recStart=0, recTimer, flushTimer, recognition, wake, audioContext, audioNode, chunksPending=0, backend={available:false,ai:false}, connections=[], briefText='', installPrompt, epoch=0, failedUploads=0, apiPending=0;
const uid=()=>crypto.randomUUID(), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), clock=s=>{s=Math.floor(s);return `${String(Math.floor(s/3600)).padStart(2,'0')}:${String(Math.floor(s/60)%60).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}, stamp=s=>clock(s).replace(/^00:/,''), date=d=>d?new Date(d+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'Date unknown';
function notice(message){$('notice').hidden=false;$('notice').textContent=message}
function quiet(){ $('notice').hidden=true }
function request(store,mode,fn){return new Promise((resolve,reject)=>{const tx=db.transaction(store,mode),req=fn(tx.objectStore(store));tx.oncomplete=()=>resolve(req?.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
const put=(s,x)=>request(s,'readwrite',o=>o.put(x)), all=s=>request(s,'readonly',o=>o.getAll()), del=(s,id)=>request(s,'readwrite',o=>o.delete(id));
async function api(path,body){apiPending++;try{const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined});if(!r.ok){let text=await r.text();throw Error(text.slice(0,220)||`Request failed (${r.status})`)}return await r.json()}finally{apiPending--}}
function fresh(){return{id:uid(),title:'Untitled event',created:new Date().toISOString(),segments:[],duration:0,brief:'',demo:false}}
async function save(){if(!db||!current)return;current.title=$('event-title').value.trim()||'Untitled event';try{await put('events',current);events=await all('events');$('history-count').textContent=events.length;$('save-status').textContent='Saved on this device'}catch(e){notice('Storage failed. Stop recording and export your data: '+e.message);$('save-status').textContent='Not saved — export now'}}
function show(view){document.body.dataset.view=view;document.querySelectorAll('.nav').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});for(const v of ['session','history','memory'])$(v+'-view').hidden=v!==view;if(view==='memory')renderMemory();if(view==='history')renderHistory()}
function renderTranscript(){const el=$('transcript');if(current.segments.length){el.innerHTML=current.segments.map(s=>`<div class="segment"><time>${stamp(s.at)}</time><p>${esc(s.text)}</p></div>`).join('');el.scrollTop=el.scrollHeight}else el.innerHTML=EMUI.empty('transcript');$('segment-count').textContent=current.segments.length+' segments'}
async function addSegments(list){current.segments.push(...list);renderTranscript();await save()}
function sourceButton(s){return `<button class="source" data-source="${esc(s.sourceId)}">↗ ${esc(s.title)} · ${esc(date(s.date))}${s.dateVerified?'':' · date unverified'}</button>`}
function wireSources(container){container.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>openSource(b.dataset.source))}
function openSource(id){const n=notes.find(x=>x.id===id);if(!n)return notice('This source has been deleted. Refresh the connections.');$('source-title').textContent=n.title;$('source-date').textContent=date(n.date)+(n.dateVerified?'':' · date unverified');$('source-body').textContent=n.text;$('source-dialog').showModal()}
let analysisVersion=0;
async function analyze(){const version=++analysisVersion, eventId=current.id;const ts=E.topics(current.segments);connections=[];if(!ts.length){$('connections').innerHTML=EMUI.empty('connections');$('empty-import').onclick=()=>show('memory');return}if(backend.ai&&notes.length){try{const result=await api('connections',{segments:current.segments,notes});if(version!==analysisVersion||eventId!==current.id)return;connections=result.connections}catch(e){notice('AI connection request failed. Showing lexical matches: '+e.message)}}if(!connections.length)connections=ts.map(t=>({topic:t.title,eventText:t.segments[0].text,at:t.segments[0].at,sources:E.retrieve(t.text,notes),message:''}));if(version!==analysisVersion)return;renderConnections()}
function renderConnections(){ $('connections').innerHTML=connections.map(c=>{const sources=c.sources.filter(s=>notes.some(n=>n.id===s.sourceId));return `<div class="connection"><div class="topic">${esc(c.topic)} · ${stamp(c.at||0)}</div><h3>${sources.length?'A thread worth picking up':'No relevant memory found'}</h3><p>${esc(c.message||(sources.length?'This event and your note share related terms. Review the source to decide whether the idea helps your work.':'Nothing in your imported notes meets the retrieval threshold for this topic.'))}</p><blockquote>${esc(c.eventText?.slice(0,250)||'')}</blockquote>${sources.map(s=>`<blockquote>“${esc(s.text.slice(0,320))}”</blockquote>${sourceButton(s)}`).join('')}<div class="muted small">${c.ai?'Semantic retrieval + AI · verify the interpretation':'Lexical baseline · not a semantic connection'}</div></div>`}).join('');wireSources($('connections'))}
async function detectBackend(){try{backend=await api('health')}catch{}$('engine-status').textContent=backend.ai?'AI ready · audio chunks transcribed every 30s':localStorage.getItem('em-speech')==='true'?'Browser speech · provider processes audio':'Local capture · enable transcription in settings';$('mode-label').textContent=backend.ai?'Local backend · AI enabled':'Offline retrieval baseline';$('memory-privacy').textContent=backend.ai?'AI mode: imported notes are sent to OpenAI for embeddings and relevant excerpts for connections. Local vectors are stored in SQLite.':'Offline mode: imported notes stay on this device. Retrieval uses lexical vectors, not semantic embeddings.';$('backend-info').textContent=backend.ai?'Local backend connected. OpenAI transcription, embeddings, and language model are enabled.':'AI backend is not configured. Run the supplied server with OPENAI_API_KEY to enable semantic search and AI answers.'}
async function begin(){if(recording||starting)return;starting=true;quiet();try{if(!navigator.mediaDevices?.getUserMedia)throw Error('Microphone capture requires HTTPS or localhost and a supported browser.');stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});if(!window.MediaRecorder)throw Error('Audio recording is unsupported in this browser.');recording=true;recStart=Date.now()-current.duration*1000;current.demo=false;await save();$('record').textContent='Stop recording';$('statusdot').classList.add('live');$('session-status').textContent='RECORDING · STAY PRESENT';$('event-title').disabled=true;for(const id of ['demo','paste-transcript','new-session'])$(id).disabled=true;try{wake=await navigator.wakeLock?.request('screen')}catch{}stream.getAudioTracks().forEach(t=>t.onended=()=>{if(recording){notice('Microphone disconnected. Capture stopped.');stop()}});if(backend.ai){await startPCM()}else{startRecorder();if(localStorage.getItem('em-speech')==='true')startSpeech();else notice('Audio is recording locally. Transcription is disabled; enable browser speech in settings or run the AI backend.')}window.dispatchEvent(new CustomEvent('eventmemory:capture-start',{detail:{stream}}));recTimer=setInterval(()=>{$('timer').textContent=clock((Date.now()-recStart)/1000);current.duration=(Date.now()-recStart)/1000},500);flushTimer=setInterval(()=>{save();analyze()},120000)}catch(e){recording=false;stream?.getTracks().forEach(t=>t.stop());notice('Could not start recording: '+e.message);resetRecordingUI()}finally{starting=false}}
function startRecorder(){const captureId=uid();const type=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(t=>MediaRecorder.isTypeSupported(t));recorder=new MediaRecorder(stream,type?{mimeType:type}:undefined);let index=0;recorder.ondataavailable=async e=>{if(!e.data.size)return;try{await put('audio',{id:uid(),eventId:current.id,index:index++,captureId,blob:e.data,kind:'container',mime:recorder.mimeType})}catch(err){notice('Audio storage failed: '+err.message);stop()}};recorder.onerror=e=>{notice('Recording error: '+(e.error?.message||'unknown'));stop()};recorder.start(5000)}
function startSpeech(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)return notice('Browser transcription is unsupported here. Audio is still saved; use the AI backend or paste a transcript.');recognition=new SR();recognition.continuous=true;recognition.interimResults=true;recognition.lang='en-US';let retry=0;recognition.onresult=e=>{retry=0;let interim='';const list=[];for(let i=e.resultIndex;i<e.results.length;i++){const r=e.results[i];if(r.isFinal)list.push({id:uid(),at:Math.max(0,(Date.now()-recStart)/1000-5),text:r[0].transcript.trim(),timing:'approximate'});else interim+=r[0].transcript}$('interim').textContent=interim;$('interim').scrollTop=$('interim').scrollHeight;if(list.length)addSegments(list)};recognition.onerror=e=>{if(!['no-speech','aborted'].includes(e.error)){notice('Speech recognition interrupted: '+e.error+'. Audio remains locally recorded.');retry=99}};recognition.onend=()=>{if(recording&&retry++<5)setTimeout(()=>{try{recognition.start()}catch{}},500);else if(recording)notice('Live transcription stopped. Audio capture continues; stop and restart to retry.');};recognition.start()}
/* Independent WAV chunks survive partial uploads and do not require container headers. */
function wav(samples,rate){const buffer=new ArrayBuffer(44+samples.length*2),v=new DataView(buffer);const str=(at,s)=>{for(let i=0;i<s.length;i++)v.setUint8(at+i,s.charCodeAt(i))};str(0,'RIFF');v.setUint32(4,36+samples.length*2,true);str(8,'WAVE');str(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,rate,true);v.setUint32(28,rate*2,true);v.setUint16(32,2,true);v.setUint16(34,16,true);str(36,'data');v.setUint32(40,samples.length*2,true);for(let i=0;i<samples.length;i++)v.setInt16(44+i*2,Math.max(-1,Math.min(1,samples[i]))*32767,true);return new Blob([buffer],{type:'audio/wav'})}
let pcm=[],pcmLength=0,pcmAt=0,uploadChain=Promise.resolve();
async function startPCM(){audioContext=new (window.AudioContext||window.webkitAudioContext)({sampleRate:16000});await audioContext.resume();const input=audioContext.createMediaStreamSource(stream);audioNode=audioContext.createScriptProcessor(4096,1,1);const silent=audioContext.createGain();silent.gain.value=0;input.connect(audioNode);audioNode.connect(silent);silent.connect(audioContext.destination);pcm=[];pcmLength=0;pcmAt=current.duration;audioNode.onaudioprocess=e=>{if(!recording)return;const sample=new Float32Array(e.inputBuffer.getChannelData(0));pcm.push(sample);pcmLength+=sample.length;if(pcmLength>=audioContext.sampleRate*30)flushPCM()}}
async function flushPCM(){if(!pcmLength)return;const data=new Float32Array(pcmLength);let i=0;for(const p of pcm){data.set(p,i);i+=p.length}const at=pcmAt;pcmAt+=pcmLength/audioContext.sampleRate;const blob=wav(data,audioContext.sampleRate);pcm=[];pcmLength=0;const entry={id:uid(),eventId:current.id,at,blob,kind:'wav',mime:'audio/wav',transcribed:false};const capturedEpoch=epoch;await put('audio',entry);chunksPending++;uploadChain=uploadChain.then(async()=>{if(capturedEpoch!==epoch)return;try{const r=await fetch('/api/transcribe',{method:'POST',headers:{'Content-Type':'audio/wav'},body:blob});if(!r.ok)throw Error(await r.text());const result=await r.json();if(capturedEpoch!==epoch)return;const ev=events.find(x=>x.id===entry.eventId)||current;if(ev.id===current.id){if(result.text)await addSegments([{id:uid(),at,text:result.text,timing:'30-second chunk start'}])}else{ev.segments.push({id:uid(),at,text:result.text,timing:'30-second chunk start'});await put('events',ev)}entry.transcribed=true;await put('audio',entry)}catch(e){failedUploads++;notice('Transcription failed. Audio is saved for export. '+e.message)}finally{chunksPending--;if(chunksPending===0)analyze()}});if(chunksPending>4)notice('Transcription is falling behind. Audio is saved locally; keep this app open until uploads finish.')}
async function retrySaved(){
 if(recording||chunksPending)return notice('Finish the current capture before retrying.');
 if(!backend.ai)return notice('Run the local AI backend to retry saved WAV chunks. Browser container recordings can be exported instead.');
 const rows=(await all('audio')).filter(a=>a.kind==='wav'&&!a.transcribed&&a.eventId===current.id);
 if(!rows.length)return notice('No unfinished WAV chunks for this event.');
 $('retry-transcription').disabled=true;chunksPending++;
 try{for(const row of rows){const r=await fetch('/api/transcribe',{method:'POST',headers:{'Content-Type':'audio/wav'},body:row.blob});if(!r.ok)throw Error(await r.text());const result=await r.json();if(result.text)await addSegments([{id:uid(),at:row.at,text:result.text,timing:'30-second chunk start'}]);row.transcribed=true;await put('audio',row)}current.segments.sort((a,b)=>a.at-b.at);await save();renderTranscript();notice('Saved audio chunks transcribed.');await analyze()}catch(e){notice('Retry interrupted; unprocessed chunks are retained: '+e.message)}finally{chunksPending--;$('retry-transcription').disabled=false}
}
function resetRecordingUI(){window.dispatchEvent(new Event('eventmemory:capture-stop'));$('record').textContent='Start recording';$('statusdot').classList.remove('live');$('session-status').textContent=chunksPending?'FINISHING TRANSCRIPTION':'SESSION SAVED';$('event-title').disabled=false;for(const id of ['demo','paste-transcript','new-session'])$(id).disabled=false;$('interim').textContent=''}
async function stop(){if(!recording)return;recording=false;window.dispatchEvent(new Event('eventmemory:capture-stop'));clearInterval(recTimer);clearInterval(flushTimer);recognition?.abort();if(recorder?.state==='recording'){await new Promise(resolve=>{recorder.addEventListener('stop',resolve,{once:true});recorder.stop()})}if(audioNode){audioNode.disconnect();await flushPCM();await audioContext.close();audioNode=null}stream?.getTracks().forEach(t=>t.stop());await wake?.release();current.duration=(Date.now()-recStart)/1000;resetRecordingUI();await save();await uploadChain;await analyze()}
async function consent(){if(recording)return stop();$('consent-check').checked=false;$('confirm-record').disabled=true;$('consent-engine').textContent=backend.ai?'AI transcription is enabled: each audio chunk is sent to OpenAI through your local server. Relevant notes and transcript text are also sent for embeddings and answers.':localStorage.getItem('em-speech')==='true'?'Browser transcription is enabled. Your browser may send audio to its speech recognition provider.':'Audio-only mode: no external transcription is enabled. You can paste a transcript or configure transcription in settings.';$('consent').showModal()}
function download(name,data,type='text/plain'){const url=URL.createObjectURL(data instanceof Blob?data:new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
async function exportAudio(){const rows=(await all('audio')).filter(x=>x.eventId===current.id);if(!rows.length)return notice('No audio is saved for this event.');if(rows[0].kind==='container'){const takes={};for(const row of rows)(takes[row.captureId||'legacy']||= []).push(row);let i=0;for(const take of Object.values(takes))download('eventmemory-take-'+(++i)+'.'+(take[0].mime.includes('mp4')?'m4a':'webm'),new Blob(take.sort((a,b)=>a.index-b.index).map(x=>x.blob),{type:take[0].mime}));if(i>1)notice(i+' recording takes exported separately. Allow multiple downloads if prompted.')}else{for(const r of rows)download(`eventmemory-${stamp(r.at).replace(':','-')}.wav`,r.blob);notice(`${rows.length} WAV chunks exported. Your browser may ask to allow multiple downloads.`)}}
function renderMemory(){$('memory-count').textContent=notes.length;$('memory-list').innerHTML=notes.length?notes.map(n=>`<div class="memorycard"><span class="row-art">${EMUI.icon('note')}</span><div><h3>${esc(n.title)}</h3><p>${date(n.date)}${n.dateVerified?'':' · date unverified'} · ${E.chunk(n.text).length} chunks</p><button class="textbtn" data-source="${n.id}">View source ↗</button></div><button class="textbtn" data-delete="${n.id}">Delete</button></div>`).join(''):EMUI.empty('memory');wireSources($('memory-list'));$('memory-list').querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{if(apiPending)return notice('Wait for AI processing to finish before deleting a note.');if(!confirm('Delete this note and its connections?'))return;await del('notes',b.dataset.delete);notes=await all('notes');if(backend.available)await api('delete-memory',{id:b.dataset.delete}).catch(e=>notice(e.message));renderMemory();await analyze()})}
async function addNote(title,text,d,verified=true){if(!text.trim())throw Error('Add some content first.');if(text.length>1500000)throw Error('Please split notes larger than 1.5 MB.');const n={id:uid(),title:title||'Untitled note',text:text.trim(),date:d||null,dateVerified:!!d&&verified};await put('notes',n);notes=await all('notes');renderMemory();if(backend.ai){try{await api('import-memory',{notes})}catch(e){notice('Note saved locally, but semantic indexing failed: '+e.message)}}return n}
function renderHistory(){$('history-list').innerHTML=events.length?events.sort((a,b)=>b.created.localeCompare(a.created)).map(e=>`<div class="historycard"><span class="row-art">${EMUI.icon('history')}</span><div><h3>${esc(e.title)}${e.demo?' · SAMPLE':''}</h3><p>${new Date(e.created).toLocaleString()} · ${clock(e.duration)} · ${e.segments.length} segments</p></div><button class="secondary" data-event="${e.id}">Open ↗</button><button class="textbtn" data-delete-event="${e.id}">Delete</button></div>`).join(''):EMUI.empty('history');$('history-list').querySelectorAll('[data-event]').forEach(b=>b.onclick=async()=>{if(recording||chunksPending)return notice('Stop recording and wait for transcription to finish before switching events.');current=events.find(e=>e.id===b.dataset.event);loadCurrent();show('session');await analyze()});$('history-list').querySelectorAll('[data-delete-event]').forEach(b=>b.onclick=async()=>{if(recording||chunksPending)return notice('Finish the current capture first.');if(!confirm('Delete this event, transcript, brief, and audio?'))return;await del('events',b.dataset.deleteEvent);for(const a of await all('audio'))if(a.eventId===b.dataset.deleteEvent)await del('audio',a.id);events=await all('events');if(current.id===b.dataset.deleteEvent){current=fresh();loadCurrent();analyze()}$('history-count').textContent=events.length;renderHistory()})}
function loadCurrent(){$('event-title').value=current.title;$('timer').textContent=clock(current.duration);renderTranscript();briefText=current.brief||'';$('brief').textContent=briefText;$('brief-panel').hidden=!briefText;$('chat').innerHTML='<p class="muted">Ask a question grounded in this transcript and your imported notes.</p>';if(current.demo)notice('Sample session — fictional transcript and notes for workflow testing.');else quiet()}
async function makeBrief(){if(!current.segments.length)return notice('Record or paste a transcript first.');const button=$('generate-brief');button.disabled=true;try{await analyze();if(backend.ai){const r=await api('brief',{segments:current.segments,notes});briefText=r.text}else{const takes=current.segments.slice(0,7).map(s=>`• [${stamp(s.at)}] ${s.text}`);const linked=connections.filter(c=>c.sources.length);briefText=`${current.title}\n${current.demo?'SAMPLE SESSION\n':''}Extractive brief · offline baseline\n\nKEY TAKEAWAYS (transcript excerpts)\n${takes.join('\n')}\n\nHOW THIS CONNECTS TO YOUR WORK\n${linked.length?linked.map(c=>`${c.topic}: related terms in ${c.sources.map(s=>`${s.title} (${date(s.date)}) [${s.sourceId}]`).join(', ')}. Review the original source; this is not a verified recommendation.`).join('\n'):'No relevant memory found.'}\n\nSUGGESTED NEXT STEPS\n• Review matched notes and verify each connection.\n• Pick one idea from the transcript and test it in a small experiment.\n\nOPEN QUESTIONS\n• Which claims need independent evidence?\n• Does the idea address the problem in the cited note?\n\nEnable the AI backend for synthesized takeaways and specific next steps.`}current.brief=briefText;$('brief').textContent=briefText;$('brief-panel').hidden=false;await save();$('brief-panel').scrollIntoView({behavior:'smooth',block:'start'})}catch(e){notice('Brief could not be generated: '+e.message)}finally{button.disabled=false}}
async function ask(e){e.preventDefault();const q=$('question').value.trim();if(!q)return;if(!current.segments.length)return notice('Add a transcript before asking a question.');$('question').value='';const user=document.createElement('div');user.className='chatmessage user';user.textContent=q;$('chat').append(user);const answer=document.createElement('div');answer.className='chatmessage';answer.textContent='Looking in your transcript and notes…';$('chat').append(answer);try{if(backend.ai){const r=await api('ask',{question:q,segments:current.segments,notes});answer.textContent=r.text}else{const matches=current.segments.map(s=>({...s,score:E.cosine(E.vector(q),E.vector(s.text))})).filter(s=>s.score>.13).sort((a,b)=>b.score-a.score).slice(0,3);const memories=E.retrieve(q,notes,2);answer.textContent='Offline evidence search (not an AI answer)\n\n'+(matches.length?matches.map(s=>`[${stamp(s.at)}] ${s.text}`).join('\n\n'):'No relevant transcript evidence found.')+(memories.length?'\n\nFrom your memory:\n'+memories.map(s=>`${s.title} · ${date(s.date)}\n“${s.text.slice(0,400)}”`).join('\n\n'):'\n\nNo relevant memory found.')}}catch(err){answer.textContent='Unable to answer: '+err.message}$('chat').scrollTop=$('chat').scrollHeight}
async function demo(){if(recording||chunksPending)return notice('Finish your capture first.');if(current.segments.length)await save();current=fresh();current.title='Building reliable AI agents · Sample';current.demo=true;current.duration=840;const samples=[['Sample · Cloud agent planning','2026-10-11','We discussed building AI agents on Google Cloud. Our CloudOps team needs an agent that diagnoses failed Kubernetes deployments. We need reliable tool permissions and a way to evaluate results before production.'],['Sample · Knowledge assistant idea','2026-10-09','I want a personal memory assistant with vector retrieval and embeddings for my past notes. It must cite the original discussion and avoid hallucinated connections.']];for(const [title,d,text] of samples)if(!notes.some(n=>n.title===title))await addNote(title,text,d);current.segments=[{id:uid(),at:12,text:'Today we will explore building AI agents with structured tools and explicit permissions.'},{id:uid(),at:135,text:'On Google Cloud, agent workflows can use Vertex AI. Keep Kubernetes deployment diagnosis read-only until you have evaluated the agent.'},{id:uid(),at:285,text:'Vector retrieval and embeddings can connect a new question to relevant personal memory. Always show the original source.'},{id:uid(),at:465,text:'Evaluation must include tool failures, irrelevant retrieval results, and unsupported claims. Measure grounded answers, not just fluent answers.'},{id:uid(),at:650,text:'For privacy, collect consent, minimize audio retention, and give the user a clear delete option.'},{id:uid(),at:810,text:'Start with a small benchmark from your real workflow before allowing autonomous actions.'}];loadCurrent();await save();await analyze()}
async function seedTestScenarios(){
 const fixtures=EMTestScenarios;
 for(const note of fixtures.notes)if(!notes.some(n=>n.id===note.id))await put('notes',structuredClone(note));
 for(const event of fixtures.events)if(!events.some(e=>e.id===event.id)){const copy=structuredClone(event);copy.brief=fixtures.brief(event,E);await put('events',copy)}
 [events,notes]=await Promise.all([all('events'),all('notes')]);
}
async function init(){db=await new Promise((resolve,reject)=>{const r=indexedDB.open('eventmemory',1);r.onupgradeneeded=()=>{for(const s of ['events','notes','audio'])r.result.createObjectStore(s,{keyPath:'id'})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});[events,notes]=await Promise.all([all('events'),all('notes')]);if(new URLSearchParams(location.search).get('examples')==='1')await seedTestScenarios();current=events.sort((a,b)=>b.created.localeCompare(a.created))[0]||fresh();loadCurrent();$('history-count').textContent=events.length;renderMemory();await detectBackend();await analyze();const incomplete=(await all('audio')).filter(a=>a.kind==='wav'&&!a.transcribed);if(incomplete.length)notice(`${incomplete.length} saved audio chunks were not transcribed. Export them from their event; recordings are preserved.`);navigator.storage?.persist?.();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});}
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>show(b.dataset.view));$('record').onclick=consent;$('consent-check').onchange=e=>$('confirm-record').disabled=!e.target.checked;$('consent').onclose=()=>{if($('consent').returnValue==='record'&&$('consent-check').checked)begin()};$('settings').onclick=()=>{$('browser-speech').checked=localStorage.getItem('em-speech')==='true';$('settings-dialog').showModal()};$('close-settings').onclick=()=>$('settings-dialog').close();$('browser-speech').onchange=e=>{if(recording){e.target.checked=!e.target.checked;return notice('Stop recording before changing transcription mode.')}localStorage.setItem('em-speech',e.target.checked);detectBackend()};$('download-audio').onclick=exportAudio;$('retry-transcription').onclick=retrySaved;$('close-source').onclick=()=>$('source-dialog').close();$('import-shortcut').onclick=()=>show('memory');$('refresh').onclick=analyze;$('demo').onclick=demo;$('generate-brief').onclick=makeBrief;$('ask-form').onsubmit=ask;$('export-transcript').onclick=()=>download('eventmemory-transcript.txt',current.segments.map(s=>`[${stamp(s.at)}] ${s.text}`).join('\n'));$('export-brief').onclick=()=>download('eventmemory-brief.md',briefText);$('event-title').onchange=save;
$('save-note').onclick=async()=>{try{await addNote($('note-title').value,$('note-content').value,$('note-date').value);$('note-title').value='';$('note-content').value='';$('note-date').value='';notice('Note imported. Connections will cite this source.');await analyze()}catch(e){notice(e.message)}};
$('note-files').onchange=async e=>{const files=[...e.target.files];let count=0;try{for(const f of files){if(f.size>1500000)throw Error(f.name+' exceeds 1.5 MB. Split the file before importing.');await addNote(f.name,E.extractJSON(await f.text()),$('note-date').value,!!$('note-date').value);count++}notice(`${count} files imported. Set original dates when known; unknown dates are never inferred.`);await analyze()}catch(err){notice(`${count} files imported. ${err.message}`)}e.target.value=''};
$('paste-transcript').onclick=()=>$('paste-dialog').showModal();$('cancel-paste').onclick=()=>$('paste-dialog').close();$('save-transcript').onclick=async()=>{const text=$('transcript-input').value.trim();if(!text)return;const list=text.split(/\n+/).filter(x=>x.trim()).map((line,i)=>{const m=line.match(/^\[?(?:(\d+):)?(\d{1,2}):(\d{2})\]?\s*(.*)$/);return{id:uid(),at:m?(Number(m[1]||0)*3600+Number(m[2])*60+Number(m[3])):current.duration+i*30,text:m?m[4]:line,timing:m?'imported':'estimated'}});await addSegments(list);current.duration=Math.max(current.duration,...list.map(s=>s.at));$('timer').textContent=clock(current.duration);$('paste-dialog').close();$('transcript-input').value='';await save();await analyze()};
$('new-session').onclick=async()=>{if(recording||chunksPending)return notice('Finish recording first.');if(current.segments.length)await save();current=fresh();loadCurrent();show('session');await analyze()};$('export-data').onclick=()=>download('eventmemory-backup.json',JSON.stringify({version:1,events,notes},null,2),'application/json');$('delete-all').onclick=async()=>{if(recording||chunksPending||apiPending)return notice('Stop recording and wait for transcription and AI processing before deleting.');if(!confirm('Permanently delete ALL events, notes, audio, and local vectors? Export anything you want to keep first.'))return;epoch++;if(backend.available){try{await api('delete-all',{})}catch(e){return notice('Backend deletion failed. Data was not cleared: '+e.message)}}for(const s of ['events','notes','audio'])await request(s,'readwrite',o=>o.clear());events=[];notes=[];current=fresh();connections=[];loadCurrent();renderMemory();$('history-count').textContent=0;await analyze();$('settings-dialog').close();notice('All EventMemory data on this device and the connected local backend was deleted.')};window.addEventListener('beforeunload',e=>{if(recording||chunksPending){e.preventDefault();e.returnValue=''}});document.addEventListener('visibilitychange',()=>{if(document.hidden&&recording)notice('App is backgrounded. Capture may be interrupted. Keep it visible for reliable recording.')});window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('install').hidden=false});$('install').onclick=async()=>{await installPrompt?.prompt();$('install').hidden=true};init().then(()=>{if(new URLSearchParams(location.search).get('examples')==='1'){show('history');notice('Three fictional test sessions are saved in History. Open TEST 1, 2, or 3 to inspect transcripts, sources, and briefs. Existing data is preserved.')}}).catch(e=>notice('Local storage could not open: '+e.message+'. Try a regular browser tab with storage enabled.'));
